import ast,base64,hashlib,json
s=base64.b64decode('').decode('utf-8')
assert hashlib.sha256(s.encode()).hexdigest()=='71d57dfd549337231bd1160ff3008374a473b305f662178609cf61e5ab300f5b'
t=ast.parse(s,filename='rog_runner.py')
compile(t,'rog_runner.py','exec')
print(json.dumps({'file':'rog_runner.py','bytes':len(s.encode()),'sha256':hashlib.sha256(s.encode()).hexdigest(),'ast_and_compile_only':True,'module_executed':False,'host_calls':0,'syntax':'passed'},sort_keys=True))
